namespace RecipeHub.Data;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Ingredients { get; set; } = string.Empty;
    public string Steps { get; set; } = string.Empty;
    public double AverageRating { get; set; }
    public int RatingCount { get; set; }
}

namespace RecipeHub.Data;

public class RecipeService
{
    private readonly List<Recipe> _recipes = new()
    {
        new Recipe { Id = 1, Title = "Classic Margherita Pizza", Category = "Italian", Ingredients = "Pizza dough, Fresh mozzarella, San Marzano tomatoes, Fresh basil, Olive oil, Salt", Steps = "1. Preheat oven to 475°F.\n2. Roll out dough on floured surface.\n3. Spread crushed tomatoes evenly.\n4. Tear mozzarella and distribute.\n5. Bake 10-12 minutes until crust is golden.\n6. Top with fresh basil and drizzle olive oil." },
        new Recipe { Id = 2, Title = "Spaghetti Carbonara", Category = "Italian", Ingredients = "Spaghetti, Guanciale, Eggs, Pecorino Romano, Black pepper", Steps = "1. Cook spaghetti in salted water.\n2. Crisp guanciale in a pan.\n3. Whisk eggs with grated pecorino and pepper.\n4. Toss hot pasta with guanciale.\n5. Remove from heat and stir in egg mixture.\n6. Serve immediately with extra pecorino." },
        new Recipe { Id = 3, Title = "Chicken Tikka Masala", Category = "Indian", Ingredients = "Chicken thighs, Yogurt, Garam masala, Tomato sauce, Cream, Onion, Garlic, Ginger", Steps = "1. Marinate chicken in yogurt and spices for 2 hours.\n2. Grill or broil chicken until charred.\n3. Sauté onion, garlic, and ginger.\n4. Add tomato sauce and simmer.\n5. Stir in cream and garam masala.\n6. Add chicken pieces and simmer 10 minutes." },
        new Recipe { Id = 4, Title = "Vegetable Biryani", Category = "Indian", Ingredients = "Basmati rice, Mixed vegetables, Onions, Yogurt, Biryani spices, Saffron, Ghee, Mint", Steps = "1. Soak basmati rice for 30 minutes.\n2. Fry onions until golden brown.\n3. Cook vegetables with spices.\n4. Layer rice and vegetables in pot.\n5. Add saffron milk and ghee.\n6. Cook on low heat (dum) for 25 minutes." },
        new Recipe { Id = 5, Title = "Beef Tacos", Category = "Mexican", Ingredients = "Ground beef, Corn tortillas, Onion, Cilantro, Lime, Salsa, Avocado, Cumin", Steps = "1. Season beef with cumin, salt, and pepper.\n2. Brown beef in a skillet.\n3. Warm tortillas on a griddle.\n4. Dice onion, chop cilantro, slice avocado.\n5. Assemble tacos with beef and toppings.\n6. Squeeze lime juice and add salsa." },
        new Recipe { Id = 6, Title = "Guacamole", Category = "Mexican", Ingredients = "Avocados, Lime juice, Red onion, Jalapeño, Cilantro, Tomato, Salt", Steps = "1. Halve and pit ripe avocados.\n2. Mash to desired consistency.\n3. Finely dice onion, jalapeño, and tomato.\n4. Mix everything together.\n5. Add lime juice and salt to taste.\n6. Serve immediately with tortilla chips." },
        new Recipe { Id = 7, Title = "Miso Ramen", Category = "Japanese", Ingredients = "Ramen noodles, Miso paste, Pork belly, Soft-boiled egg, Green onions, Nori, Chicken broth", Steps = "1. Simmer chicken broth with miso paste.\n2. Slice and sear pork belly.\n3. Cook ramen noodles according to package.\n4. Prepare soft-boiled eggs (6.5 minutes).\n5. Assemble bowls with noodles and broth.\n6. Top with pork, egg, nori, and green onions." },
        new Recipe { Id = 8, Title = "Teriyaki Salmon", Category = "Japanese", Ingredients = "Salmon fillets, Soy sauce, Mirin, Brown sugar, Garlic, Ginger, Sesame seeds, Rice", Steps = "1. Mix soy sauce, mirin, sugar, garlic, and ginger.\n2. Marinate salmon for 30 minutes.\n3. Preheat oven to 400°F.\n4. Bake salmon 12-15 minutes.\n5. Brush with extra teriyaki glaze.\n6. Serve over rice with sesame seeds." },
    };

    private readonly Dictionary<int, List<int>> _ratings = new();

    public List<string> GetCategories() =>
        _recipes.Select(r => r.Category).Distinct().OrderBy(c => c).ToList();

    public List<Recipe> GetRecipesByCategory(string category) =>
        _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

    public Recipe? GetRecipe(int id) => _recipes.FirstOrDefault(r => r.Id == id);

    public void AddRating(int recipeId, int stars)
    {
        if (stars < 1 || stars > 5) return;

        if (!_ratings.ContainsKey(recipeId))
            _ratings[recipeId] = new List<int>();

        _ratings[recipeId].Add(stars);

        var recipe = GetRecipe(recipeId);
        if (recipe is not null)
        {
            recipe.RatingCount = _ratings[recipeId].Count;
            recipe.AverageRating = _ratings[recipeId].Average();
        }
    }

    public void SubmitRecipe(string title, string category, string ingredients, string steps)
    {
        var newId = _recipes.Max(r => r.Id) + 1;
        _recipes.Add(new Recipe
        {
            Id = newId,
            Title = title,
            Category = category,
            Ingredients = ingredients,
            Steps = steps
        });
    }
}

