arguments.file_text:
@page "/"

<PageTitle>RecipeHub - Recipe Sharing Community</PageTitle>

<h1>Welcome to RecipeHub</h1>
<p class="lead">Discover and share delicious recipes from around the world.</p>

<h2>Browse by Category</h2>
<div class="row">
    @foreach (var category in Categories)
    {
        <div class="col-md-3 mb-4">
            <div class="card h-100">
                <div class="card-body text-center">
                    <h5 class="card-title">@category</h5>
                    <a href="category/@category" class="btn btn-primary">Browse Recipes</a>
                </div>
            </div>
        </div>
    }
</div>

<div class="mt-4">
    <h3>Share Your Recipes</h3>
    <p>Have a great recipe? Share it with the community!</p>
    <a href="submit" class="btn btn-success">Submit a Recipe</a>
</div>

@code {
    [Inject] public RecipeHub.Data.RecipeService RecipeService { get; set; } = default!;

    private List<string> Categories { get; set; } = new();

    protected override void OnInitialized()
    {
        Categories = RecipeService.GetCategories();
    }
}

@page "/category/{CategoryName}"

<PageTitle>@CategoryName Recipes - RecipeHub</PageTitle>

<h1>@CategoryName Recipes</h1>

@if (Recipes.Any())
{
    <div class="row">
        @foreach (var recipe in Recipes)
        {
            <div class="col-md-6 mb-4">
                <div class="card h-100">
                    <div class="card-body">
                        <h5 class="card-title">@recipe.Title</h5>
                        <p class="card-text text-muted">
                            @if (recipe.RatingCount > 0)
                            {
                                <span>⭐ @recipe.AverageRating.ToString("F1") (@recipe.RatingCount ratings)</span>
                            }
                            else
                            {
                                <span>No ratings yet</span>
                            }
                        </p>
                        <a href="recipe/@recipe.Id" class="btn btn-outline-primary">View Recipe</a>
                    </div>
                </div>
            </div>
        }
    </div>
}
else
{
    <p>No recipes found in this category.</p>
}

<a href="/" class="btn btn-secondary mt-3">← Back to Categories</a>

@code {
    [Parameter] public string CategoryName { get; set; } = string.Empty;
    [Inject] public RecipeHub.Data.RecipeService RecipeService { get; set; } = default!;

    private List<RecipeHub.Data.Recipe> Recipes { get; set; } = new();

    protected override void OnInitialized()
    {
        Recipes = RecipeService.GetRecipesByCategory(CategoryName);
    }
}

@page "/recipe/{RecipeId:int}"

<PageTitle>@(Recipe?.Title ?? "Recipe") - RecipeHub</PageTitle>

@if (Recipe is not null)
{
    <h1>@Recipe.Title</h1>
    <span class="badge bg-secondary mb-3">@Recipe.Category</span>

    <h3 class="mt-4">Ingredients</h3>
    <ul>
        @foreach (var ingredient in Recipe.Ingredients.Split(',', StringSplitOptions.TrimEntries))
        {
            <li>@ingredient</li>
        }
    </ul>

    <h3 class="mt-4">Steps</h3>
    <ol>
        @foreach (var step in Recipe.Steps.Split('\n', StringSplitOptions.RemoveEmptyEntries))
        {
            var text = step.TrimStart();
            if (text.Length > 2 && text[1] == '.' && char.IsDigit(text[0]))
                text = text[3..];
            else if (text.Length > 3 && text[2] == '.' && char.IsDigit(text[0]) && char.IsDigit(text[1]))
                text = text[4..];
            <li>@text.Trim()</li>
        }
    </ol>

    <h3 class="mt-4">Rate this Recipe</h3>
    <StarRating RecipeId="Recipe.Id" />

    <a href="category/@Recipe.Category" class="btn btn-secondary mt-4">← Back to @Recipe.Category</a>
}
else
{
    <p>Recipe not found.</p>
    <a href="/" class="btn btn-secondary">← Back to Home</a>
}

@code {
    [Parameter] public int RecipeId { get; set; }
    [Inject] public RecipeHub.Data.RecipeService RecipeService { get; set; } = default!;

    private RecipeHub.Data.Recipe? Recipe { get; set; }

    protected override void OnInitialized()
    {
        Recipe = RecipeService.GetRecipe(RecipeId);
    }
}

@rendermode InteractiveServer

<div class="star-rating">
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <span class="star @(star <= SelectedRating ? "selected" : "")"
              @onclick="() => Rate(star)"
              style="cursor: pointer; font-size: 1.5rem;">
            @(star <= SelectedRating ? "★" : "☆")
        </span>
    }

    @if (SelectedRating > 0)
    {
        <span class="ms-2 text-muted">You rated this @SelectedRating/5</span>
    }

    @if (CurrentAverage > 0)
    {
        <div class="mt-1 small text-muted">
            Average: @CurrentAverage.ToString("F1") ★ (@TotalRatings ratings)
        </div>
    }
</div>

@code {
    [Parameter] public int RecipeId { get; set; }
    [Inject] public RecipeHub.Data.RecipeService RecipeService { get; set; } = default!;

    private int SelectedRating { get; set; }
    private double CurrentAverage { get; set; }
    private int TotalRatings { get; set; }

    protected override void OnInitialized()
    {
        LoadRating();
    }

    private void Rate(int stars)
    {
        SelectedRating = stars;
        RecipeService.AddRating(RecipeId, stars);
        LoadRating();
    }

    private void LoadRating()
    {
        var recipe = RecipeService.GetRecipe(RecipeId);
        if (recipe is not null)
        {
            CurrentAverage = recipe.AverageRating;
            TotalRatings = recipe.RatingCount;
        }
    }
}

@page "/submit"
@rendermode InteractiveServer

<PageTitle>Submit a Recipe - RecipeHub</PageTitle>

<h1>Submit a Recipe</h1>
<p>Share your favorite recipe with the community.</p>

@if (Submitted)
{
    <div class="alert alert-success">
        <h4>Recipe Submitted!</h4>
        <p>Thank you for sharing "<strong>@Model.Title</strong>" with the community.</p>
        <a href="/" class="btn btn-primary">Back to Home</a>
    </div>
}
else
{
    <EditForm Model="Model" OnValidSubmit="HandleSubmit" FormName="submit-recipe">
        <DataAnnotationsValidator />
        <ValidationSummary class="text-danger" />

        <div class="mb-3">
            <label for="title" class="form-label">Recipe Title</label>
            <InputText id="title" class="form-control" @bind-Value="Model.Title" />
            <ValidationMessage For="() => Model.Title" />
        </div>

        <div class="mb-3">
            <label for="category" class="form-label">Category</label>
            <InputSelect id="category" class="form-select" @bind-Value="Model.Category">
                <option value="">-- Select a category --</option>
                <option value="Italian">Italian</option>
                <option value="Indian">Indian</option>
                <option value="Mexican">Mexican</option>
                <option value="Japanese">Japanese</option>
                <option value="Other">Other</option>
            </InputSelect>
            <ValidationMessage For="() => Model.Category" />
        </div>

        <div class="mb-3">
            <label for="ingredients" class="form-label">Ingredients (comma-separated)</label>
            <InputTextArea id="ingredients" class="form-control" rows="4" @bind-Value="Model.Ingredients" />
            <ValidationMessage For="() => Model.Ingredients" />
        </div>

        <div class="mb-3">
            <label for="steps" class="form-label">Steps (one per line)</label>
            <InputTextArea id="steps" class="form-control" rows="6" @bind-Value="Model.Steps" />
            <ValidationMessage For="() => Model.Steps" />
        </div>

        <button type="submit" class="btn btn-success">Submit Recipe</button>
        <a href="/" class="btn btn-secondary ms-2">Cancel</a>
    </EditForm>
}

